argv:
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)
$sid='gts9-readonly-chime-'+[Guid]::NewGuid().ToString()
try {
 Register-CimIndicationEvent -Namespace root/cimv2 -Query 'SELECT * FROM Win32_DeviceChangeEvent' -SourceIdentifier $sid | Out-Null
 [ordered]@{kind='listener-start';time=(Get-Date).ToString('o')} | ConvertTo-Json -Compress
 $watch=[Diagnostics.Stopwatch]::StartNew();$count=0
 while($watch.Elapsed.TotalSeconds -lt 50) {
   Wait-Event -SourceIdentifier $sid -Timeout 1 | Out-Null
   foreach($ev in @(Get-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue)) {
     $count++;$n=$ev.SourceEventArgs.NewEvent
     [ordered]@{kind='device-change';received=(Get-Date).ToString('o');event_type=$n.EventType;source_time=[DateTime]::FromFileTimeUtc([long]$n.TIME_CREATED).ToString('o')} | ConvertTo-Json -Compress
     Remove-Event -EventIdentifier $ev.EventIdentifier
   }
 }
 [ordered]@{kind='listener-end';time=(Get-Date).ToString('o');seconds=$watch.Elapsed.TotalSeconds;event_count=$count} | ConvertTo-Json -Compress
} finally { Unregister-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue }
